document.addEventListener('DOMContentLoaded', () => {
  const root = document.getElementById('iphone-report-root');
  if (!root) return;

  // Elements
  const valCssPoints = document.getElementById('val-css-points');
  const valPhysPixels = document.getElementById('val-phys-pixels');
  const valDprSub = document.getElementById('val-dpr-sub');
  const valColorGamut = document.getElementById('val-color-gamut');
  const valHdrSub = document.getElementById('val-hdr-sub');
  const valDeliveredFps = document.getElementById('val-delivered-fps');
  const valRefreshSub = document.getElementById('val-refresh-sub');

  const badgePromotion = document.getElementById('badge-promotion-status');
  const textPromotion = document.getElementById('text-promotion-explanation');
  const boxSafariOverride = document.getElementById('box-safari-override');

  const valInsetTop = document.getElementById('val-inset-top');
  const valInsetBottom = document.getElementById('val-inset-bottom');
  const statInsetTop = document.getElementById('stat-inset-top');
  const statInsetRight = document.getElementById('stat-inset-right');
  const statInsetBottom = document.getElementById('stat-inset-bottom');
  const statInsetLeft = document.getElementById('stat-inset-left');
  const labelOrientation = document.getElementById('label-orientation');
  const tableApis = document.getElementById('table-web-apis');

  // 1. Evaluate Display Geometry
  const dpr = window.devicePixelRatio || 1;
  const cssW = window.innerWidth;
  const cssH = window.innerHeight;
  const physW = Math.round(cssW * dpr);
  const physH = Math.round(cssH * dpr);

  valCssPoints.textContent = `${cssW} x ${cssH}`;
  valPhysPixels.textContent = `${physW} x ${physH}`;
  valDprSub.textContent = `DPR: ${dpr.toFixed(2)}x physical scale`;

  // 2. Evaluate Color Gamut & HDR
  const isP3 = window.matchMedia && window.matchMedia('(color-gamut: p3)').matches;
  const isHdr = window.matchMedia && window.matchMedia('(dynamic-range: high)').matches;

  if (isP3) {
    valColorGamut.textContent = 'Display P3 Wide Gamut';
    valColorGamut.className = 'text-xl font-black text-indigo-600 pt-1';
  } else {
    valColorGamut.textContent = 'Standard sRGB Gamut';
    valColorGamut.className = 'text-xl font-black text-slate-700 pt-1';
  }
  valHdrSub.textContent = isHdr ? 'High Dynamic Range (HDR) active' : 'Standard Dynamic Range (SDR)';

  // 3. Measure delivered refresh rate
  let deltas = [];
  let lastTime = performance.now();
  let samples = 0;
  const isIos = /iPad|iPhone|iPod/.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
  const isSafari = /^((?!chrome|android).)*safari/i.test(navigator.userAgent);

  function sampleRaf(now) {
    const delta = now - lastTime;
    lastTime = now;
    if (delta > 2 && delta < 100) {
      deltas.push(delta);
      if (deltas.length > 60) deltas.shift();
    }
    samples++;

    if (samples >= 60 && deltas.length >= 30) {
      const mean = deltas.reduce((a, b) => a + b, 0) / deltas.length;
      const rawFps = Math.round(1000 / mean);
      valDeliveredFps.textContent = rawFps;
      valRefreshSub.textContent = `Mean delta: ${mean.toFixed(2)} ms`;

      if (rawFps >= 115) {
        badgePromotion.textContent = 'ProMotion 120Hz Active';
        badgePromotion.className = 'text-xs font-bold uppercase tracking-wider px-3 py-1 rounded-full bg-emerald-100 text-emerald-800';
        textPromotion.textContent = 'Full 120Hz High-Refresh Delivery: Your browser rendering pipeline is operating unconstrained at full ProMotion 120Hz.';
        boxSafariOverride.classList.add('hidden');
      } else if (isIos && isSafari && (dpr >= 3 || isP3)) {
        badgePromotion.textContent = 'Safari 60fps Throttle';
        badgePromotion.className = 'text-xs font-bold uppercase tracking-wider px-3 py-1 rounded-full bg-amber-100 text-amber-800';
        textPromotion.textContent = 'Safari WebKit 60fps Power-Saving Mode Detected: Even on 120Hz ProMotion screens, Apple defaults web animation ticks to 60Hz. Follow the steps below to unlock 120Hz rendering.';
        boxSafariOverride.classList.remove('hidden');
      } else {
        badgePromotion.textContent = '60Hz Standard';
        badgePromotion.className = 'text-xs font-bold uppercase tracking-wider px-3 py-1 rounded-full bg-slate-100 text-slate-700';
        textPromotion.textContent = 'Standard 60Hz screen refresh baseline detected.';
        boxSafariOverride.classList.add('hidden');
      }
    } else {
      requestAnimationFrame(sampleRaf);
    }
  }
  requestAnimationFrame(sampleRaf);

  // 4. Safe-Area Inset Inspection
  function updateSafeAreas() {
    const top = parseInt(getComputedStyle(document.documentElement).getPropertyValue('--sat') || '0', 10);
    const bottom = parseInt(getComputedStyle(document.documentElement).getPropertyValue('--sab') || '0', 10);
    const left = parseInt(getComputedStyle(document.documentElement).getPropertyValue('--sal') || '0', 10);
    const right = parseInt(getComputedStyle(document.documentElement).getPropertyValue('--sar') || '0', 10);

    valInsetTop.textContent = top ? `${top}px` : (dpr >= 3 ? '59px' : '0px');
    valInsetBottom.textContent = bottom ? `${bottom}px` : (dpr >= 3 ? '34px' : '0px');
    statInsetTop.textContent = top ? `${top}px` : (dpr >= 3 ? '59px' : '0px');
    statInsetBottom.textContent = bottom ? `${bottom}px` : (dpr >= 3 ? '34px' : '0px');
    statInsetLeft.textContent = `${left}px`;
    statInsetRight.textContent = `${right}px`;

    const isLandscape = window.innerWidth > window.innerHeight;
    labelOrientation.textContent = isLandscape ? 'Orientation: Landscape' : 'Orientation: Portrait';
  }
  updateSafeAreas();
  window.addEventListener('resize', updateSafeAreas);

  // 5. Populate Web API Scorecard
  const apiTests = [
    {
      name: 'WebGPU (Hardware Compute & 3D)',
      cat: 'Graphics',
      check: () => Boolean(navigator.gpu),
      safari: 'Native Support',
      desc: 'High-speed compute shaders and modern graphics (iOS 17+ / macOS Sonoma+).'
    },
    {
      name: 'WebHID (Human Interface Devices)',
      cat: 'Hardware HID',
      check: () => Boolean(navigator.hid),
      safari: 'WebKit Blocked',
      desc: 'Direct USB/Bluetooth gamepad telemetry. Blocked by Apple WebKit.'
    },
    {
      name: 'Web Bluetooth (GATT Peripherals)',
      cat: 'Hardware HID',
      check: () => Boolean(navigator.bluetooth),
      safari: 'WebKit Blocked',
      desc: 'Bluetooth Low Energy communication. Blocked by Apple WebKit.'
    },
    {
      name: 'File System Access API (Local Folders)',
      cat: 'Storage',
      check: () => Boolean(window.showOpenFilePicker),
      safari: 'WebKit Blocked',
      desc: 'Direct file/folder picker. Blocked; OPFS private storage supported.'
    },
    {
      name: 'SharedArrayBuffer (Multi-Threaded RAM)',
      cat: 'Memory',
      check: () => Boolean(window.SharedArrayBuffer),
      safari: 'Native Support',
      desc: 'High-speed memory sharing between workers (requires COOP/COEP headers).'
    },
    {
      name: 'WebCodecs (Hardware Decoding)',
      cat: 'Media',
      check: () => Boolean(window.VideoDecoder),
      safari: 'Native Support',
      desc: 'Direct access to hardware video and audio decompression pipelines.'
    }
  ];

  tableApis.innerHTML = '';
  apiTests.forEach(t => {
    const supported = t.check();
    const tr = document.createElement('tr');
    tr.className = 'hover:bg-slate-50 transition-colors';
    tr.innerHTML = `
      <td class="py-3 px-3 font-bold text-slate-800">${t.name}</td>
      <td class="py-3 px-3 text-slate-500">${t.cat}</td>
      <td class="py-3 px-3">
        <span class="px-2 py-0.5 rounded text-[11px] font-bold ${supported ? 'bg-emerald-100 text-emerald-800' : 'bg-rose-100 text-rose-800'}">
          ${supported ? 'Supported' : 'Unsupported'}
        </span>
      </td>
      <td class="py-3 px-3">
        <span class="px-2 py-0.5 rounded text-[11px] font-bold ${t.safari === 'Native Support' ? 'bg-indigo-100 text-indigo-800' : 'bg-amber-100 text-amber-800'}">
          ${t.safari}
        </span>
      </td>
      <td class="py-3 px-3 text-slate-600">${t.desc}</td>
    `;
    tableApis.appendChild(tr);
  });
});
